import java.util.ArrayList;
import java.util.List;

public class FarmersMarketApp {
    public static void main(String[] args) {
        List<MarketProduct> products = new ArrayList<>();
        products.add(new MarketProduct("Heirloom Tomatoes", "Sunny Acres", 4.50, "Vegetables", "Summer", true));
        products.add(new MarketProduct("Sweet Corn", "Riverbend Farm", 3.25, "Vegetables", "Summer", false));
        products.add(new MarketProduct("Honeycrisp Apples", "Hilltop Orchard", 5.00, "Fruit", "Fall", true));
        products.add(new MarketProduct("Goat Cheese", "Clover Dairy", 8.75, "Dairy", "Year-round", false));
        products.add(new MarketProduct("Wildflower Honey", "Beeline Apiary", 12.00, "Pantry", "Year-round", true));

        System.out.println("All products at the market:");
        for (MarketProduct product : products) {
            System.out.println("  " + product);
        }

        System.out.println("\nOrganic products only:");
        for (MarketProduct product : products) {
            if (product.isOrganic()) {
                System.out.println("  " + product.getName() + " from " + product.getVendor());
            }
        }
    }
}
